mapper.select:
SELECT a.*,b.id as 企业类型ID,b.类型名称 as 类型名称 FROM `外企监测_企业库_企业信息` a
left join 外企监测_企业库_企业类型 b on a.企业类型ID = b.ID


        AND a.`企业名称` LIKE CONCAT('%', #{企业名称}, '%')


        AND a.`所属行业` LIKE CONCAT('%', #{所属行业}, '%')


        AND a.`企业状态` = #{企业状态}



        AND a.`录入时间` >= #{startTime}


        AND a.`录入时间` <= #{endTime}


        and a.企业类型ID = #{企业类型ID}


order by a.id desc
